// Input: items coming from the previous HTTP Request node
// Each item is expected to have a JSON structure like your ClickUp output

return items.map(item => {
    const task = item.json;

    // Extract the 'Assigned to' custom field
    const assignedField = task.custom_fields.find(f => f.name === "Assigned to");
    const assignedTo = assignedField ? assignedField.value : "";

    return {
        json: {
            name: task.name || "",
            description: task.description || "",
            assigned_to: assignedTo,
            due_date: task.due_date ? new Date(Number(task.due_date)).toISOString() : null,
            priority: task.priority ? task.priority.priority : "",
            url: task.url || ""
        }
    };
});
